      const [f1Freq, f2Freq] = FORMANTS[vowel] || FORMANTS.i;
      const now = this.ctx.currentTime + delay;
      const osc = this.ctx.createOscillator(), sub = this.ctx.createOscillator();
      const lfo = this.ctx.createOscillator(), lfoG = this.ctx.createGain();
      osc.type = wave; sub.type = 'sine';
