      sub.frequency.setValueAtTime(f0Start * 2, now); sub.frequency.exponentialRampToValueAtTime(Math.max(160, f0End * 2), now + dur);
      lfo.frequency.value = vibratoRate; lfoG.gain.value = vibratoDepth; lfo.connect(lfoG); lfoG.connect(osc.frequency);
      const f1 = this.ctx.createBiquadFilter(); f1.type = 'bandpass'; f1.frequency.setValueAtTime(f1Freq, now); f1.Q.value = 3.2;
      const f2 = this.ctx.createBiquadFilter(); f2.type = 'bandpass'; f2.frequency.setValueAtTime(f2Freq, now); f2.Q.value = 4.2;
      const env = this.ctx.createGain();
      env.gain.setValueAtTime(0.0001, now); env.gain.linearRampToValueAtTime(vol, now + Math.min(0.028, dur * 0.28));
      env.gain.exponentialRampToValueAtTime(0.0001, now + dur);
      osc.connect(f1); osc.connect(f2); sub.connect(f2); f1.connect(env); f2.connect(env);
      env.connect(this.master); env.connect(this.delayNode);
