        if (size < 60) continue;
        if (key === 'rayakan' || key === 'ide') spawnParticles(v.w / 2, v.h / 2 - size * 0.17, size, '✦', 8);
        else if (key === 'approve') spawnParticles(v.w / 2, v.h / 2 - size * 0.11, size, '✦', 6);
        else if (key === 'reject') spawnParticles(v.w / 2, v.h / 2 - size * 0.11, size, '✖', 6);
